import { randomUUID } from "node:crypto";
import type { PrismaClient, Prisma } from "@prisma/client";
import type { Request, Response } from "express";
import { database } from "@eventflow/database";
import type { CreateUserInput } from "../schemas/user.schema.js";
import { injectTraceparent } from "../tracing.js";

export function buildCreateUserHandler(
  prisma: PrismaClient = database,
): (request: Request, response: Response) => Promise<void> {
  return async (request: Request, response: Response): Promise<void> => {
    const user = request.body as CreateUserInput;
    const userId = randomUUID();

    try {
      const event = await prisma.$transaction(async (transaction) =>
        transaction.outboxEvent.create({
          data: {
            aggregateId: userId,
            eventType: "user.created",
            payload: injectTraceparent({
              userId,
              email: user.email,
              name: user.name,
            }) satisfies Prisma.InputJsonObject,
            status: "PENDING",
          },
        }),
      );

      response.status(201).json({
        success: true,
        eventId: event.id,
      });
    } catch (error: unknown) {
      console.error("[api] Error creando el evento user.created:", error);
      response.status(500).json({
        success: false,
        error: {
          code: "INTERNAL_SERVER_ERROR",
          message: "No se pudo crear el evento de usuario",
        },
      });
    }
  };
}

export async function createUserHandler(
  request: Request,
  response: Response,
): Promise<void> {
  await buildCreateUserHandler()(request, response);
}
